 const positions=y.annualPalaces;
 function placement(row){const p=natalByName.get(row.natal);return{index:row.index,branch:row.branch,natal:row.natal,decadal:row.decadal,annual:row.annual,stars:copy(p.major),ownStars:row.stars.slice()};}
 function frame(scope){const center=positions.find(p=>p[scope]==='命宫');const at=i=>placement(positions.find(p=>p.index===(i+12)%12));return{scope,label:scope==='natal'?'本命':scope==='decadal'?(y.scopeName==='童限'?'童限参照':'大限'):'流年',center:placement(center),trines:[at(center.index+4),at(center.index+8)],opposite:at(center.index+6),empty:center.stars.length===0,borrowedStars:center.stars.length?[]:at(center.index+6).ownStars};}
 const frames={natal:frame('natal'),decadal:frame('decadal'),annual:frame('annual')};
 const layerDefs=[['natal','生年',y.natalMutations],['decadal',y.scopeName==='童限'?'童限参照':'大限',y.decadalMutations],['annual','流年',y.annualMutations]];
 const mutations=[];
 for(const[layer,label,list]of layerDefs)list.forEach((m,i)=>{const p=positions.find(p=>p.natal===m.natalPalace);mutations.push({...copy(m),layer,label,id:layer+'-'+m.star+'-'+m.type,placements:placement(p),sourcePath:`LIFE_DATA.years[${year-2000}].${layer}Mutations[${i}]`});});
 const overlapStars=[...new Set(mutations.map(m=>m.star))];
 const overlaps=overlapStars.map(star=>({star,mutations:mutations.filter(m=>m.star===star)})).filter(o=>new Set(o.mutations.map(m=>m.layer)).size>1).map(o=>({...o,id:'overlap-'+o.star,placements:o.mutations[0].placements,hasTension:o.mutations.some(m=>m.type==='忌')&&o.mutations.some(m=>m.type!=='忌')}));
 const evidence=[];const score=Object.fromEntries(order.map(id=>[id,0])),reasons=Object.fromEntries(order.map(id=>[id,[]]));
 function add(ids,value,id){for(const key of ids||[]){score[key]+=value;reasons[key].push(id);}}
 function frameText(f){const own=f.center.stars.map(s=>s.name+(s.brightness?'（'+s.brightness+'）':'')).join('、');const at=p=>p.branch+'·本命'+p.natal+'['+(p.ownStars.join('、')||'无十四主星')+']';return`${f.label}命宫在${f.center.branch}，叠本命${f.center.natal}：${own||'无十四主星，对宫'+f.borrowedStars.join('、')+'仅作参照，不移入本宫'}。三合会照${f.trines.map(at).join('、')}；对宫${at(f.opposite)}。`;}
 for(const scope of ['natal','decadal','annual']){const f=frames[scope],id='frame-'+scope,ids=palaceThemes[f.center.natal]||[];evidence.push({id,kind:'frame',text:frameText(f),placements:[f.center,...f.trines,f.opposite],themeIds:[...new Set([...ids,...f.center.ownStars.flatMap(star=>starThemes[star]||[])])],sourcePath:'LIFE_DATA.years['+(year-2000)+'].annualPalaces'});if(scope!=='natal'){add(ids,scope==='annual'?5.2:1.8,id);for(const s of f.center.ownStars)add(starThemes[s],scope==='annual'?1.1:.45,id);}}
 for(const m of mutations){const p=m.placements;const ids=[...new Set([...(palaceThemes[p.annual]||[]),...(palaceThemes[p.natal]||[]),...(starThemes[m.star]||[])])];const text=`${m.label}${m.star}化${m.type}，在${p.branch}：本命${p.natal}／${frames.decadal.label}${p.decadal}／流年${p.annual}。`;evidence.push({id:m.id,kind:'mutation',text,placements:[p],themeIds:ids,layer:m.layer,star:m.star,type:m.type,sourcePath:m.sourcePath});const value={禄:2.8,权:2.5,科:1.9,忌:3.3}[m.type]*(m.layer==='annual'?1:m.layer==='decadal'?.28:.12);add(palaceThemes[p.annual],value,m.id);add(palaceThemes[p.natal],value*.42,m.id);if(m.layer==='annual')add(starThemes[m.star],.4,m.id);}
 for(const o of overlaps){const p=o.placements,ids=[...new Set([...(palaceThemes[p.natal]||[]),...(starThemes[o.star]||[])])];const text=`${o.star}同星${o.mutations.length===3?'三层':'跨层'}叠化：${o.mutations.map(m=>m.label+'化'+m.type).join('、')}；同在本命${p.natal}（${p.branch}），叠${frames.decadal.label}${p.decadal}／流年${p.annual}。${o.hasTension?'禄、权、科与忌的语义分别保留，不相抵成单一吉凶。':''}`;evidence.push({id:o.id,kind:'same-star-overlap',text,placements:[p],themeIds:ids});if(o.mutations.some(m=>m.layer==='annual'))add(ids,o.hasTension?1.4:.8,o.id);}
