 const machine=overlaps.find(o=>o.star==='天机'&&o.mutations.some(m=>m.layer==='decadal'&&m.type==='禄')&&o.mutations.some(m=>m.layer==='annual'&&m.type==='权'));
 const previous=rows.get(year-1),changed=Boolean(previous&&previous.decadeId!==y.decadeId&&y.scopeName!=='童限');
 let forced=null,human;
